const clamp = (n,a,b) => Math.max(a,Math.min(b,n));
const noise = n => { const v = Math.sin(n*127.1+311.7)*43758.5453; return v-Math.floor(v); };
const overlap = (a,b) => a.x < b.x+b.w && a.x+a.w > b.x && a.y < b.y+b.h && a.y+a.h > b.y;
