function showMap(){if(state!=='play')return;state='map';keys.clear();$('mapContent').replaceChildren();realms.forEach((r,i)=>{const block=document.createElement('div');block.className='realm-map';const h=document.createElement('h3');h.textContent=r.label;block.append(h);const track=document.createElement('div');track.className='map-track';const names=[`✦ ${i===0?'Szél':i===1?'Árnyék':'Emlék'}`,'⛩ Átjáró','◆ Őrző'];names.forEach((name,n)=>{const el=document.createElement('div');el.className='map-node'+(i===realm&&((player.x<900&&n===0)||(player.x>=900&&player.x<2800&&n===1)||(player.x>=2800&&n===2))?' active':'')+(i>realm?' locked':'');const status=n===0?(i<2?(abilities[i]?'megszerezve':'szentély'):'hajnalkard'):n===1?(defeated[i]?'megnyílt':'lezárva'):(defeated[i]?'legyőzve':'vár rád');el.textContent=name+' · '+status;if(el.classList.contains('active'))el.prepend('● ');track.append(el);});block.append(track);$('mapContent').append(block);});$('map').hidden=false;$('closeMap').focus();}
function closeMap(){$('map').hidden=true;state='play';pressed.clear();}
function pause(){if(state==='play'){state='pause';keys.clear();$('pause').hidden=false;$('resumeButton').focus();}else if(state==='pause'){state='play';$('pause').hidden=true;pressed.clear();}}
function mainMenu(){state='menu';for(const id of ['dialog','map','pause','prompt','bossHud'])$(id).hidden=true;$('menu').hidden=false;showHUD(false);keys.clear();$('continueButton').hidden=!saved;}
$('startButton').onclick=()=>startGame(false);$('continueButton').onclick=()=>startGame(true);$('pauseButton').onclick=pause;$('resumeButton').onclick=pause;$('mainMenuButton').onclick=mainMenu;$('mapButton').onclick=showMap;$('closeMap').onclick=closeMap;
$('helpButton').onclick=()=>{story('AZ ÖSVÉNY SZABÁLYAI','Kard, szél és emlékezet.','A/D vagy a nyilak: mozgás. Space: ugrás. J: kardcsapás. E: szentély, kapu és történet. M: térkép. Esc: szünet. A szél áldásával kétszer ugorhatsz; az árnyék szentélye után K-val szellemléphetsz. Először indulj balra a magas szentélyhez, utána keletre az őrzőhöz. Győzelem után térj vissza a középső kapuhoz. A nagy őrzők arany villanása támadást jelez: ugorj félre, és a csapás után támadj!',mainMenu);};
$('soundButton').onclick=()=>{sound=!sound;$('soundButton').textContent=sound?'Hang: be':'Hang: ki';if(sound){tone(440,.2);audio?.resume();}};
function keyName(e){return e.code==='Space'||e.key==='Spacebar'?' ':e.key.toLowerCase();}
function handleKeyDown(e){const k=keyName(e);if([' ','arrowup','arrowdown','arrowleft','arrowright'].includes(k))e.preventDefault();if(e.repeat)return;if(k==='escape'){if(state==='map')closeMap();else pause();return;}if(k==='m'){if(state==='map')closeMap();else showMap();return;}if(state==='play'){keys.add(k);pressed.add(k);}}
function handleKeyUp(e){keys.delete(keyName(e));}
addEventListener('keydown',handleKeyDown);addEventListener('keyup',handleKeyUp);addEventListener('blur',()=>{keys.clear();pressed.clear();if(state==='play')pause();});
document.querySelectorAll('[data-key]').forEach(b=>{b.addEventListener('pointerdown',e=>{e.preventDefault();if(state!=='play')return;b.setPointerCapture(e.pointerId);keys.add(b.dataset.key);pressed.add(b.dataset.key);});for(const event of ['pointerup','pointercancel','lostpointercapture'])b.addEventListener(event,()=>keys.delete(b.dataset.key));});
sheet.onload=()=>{loadingReady=true;};sheet.onerror=()=>{toast('Kiba képe nem töltődött be. Frissítsd az oldalt.');};if(sheet.complete&&sheet.naturalWidth)loadingReady=true;
function frame(ms){const dt=Math.min((ms-last)/1000||0,.033);last=ms;update(dt);draw();requestAnimationFrame(frame);}requestAnimationFrame(frame);
// Read-only state snapshot for QA and future extensions.
window.kiba={getState:()=>({state,realm,abilities:[...abilities],defeated:[...defeated],shards,player:player?{...player}:null,boss:boss?{...boss}:null,checkpoint,gateOpen}),version:'0.1.1'};
